import sys, math, copy
sys.path.insert(0,'/tmp/work/calc')
from evaluate import *

def r3(x):  # round to 3 dp
    return round(x + 1e-12, 3)

class Builder:
    def __init__(self):
        self.acts = []
        self.crew_free = {}
        self.skid_free = {s: SKIDS[s]['avail_h'] for s in SKIDS}
        self.stage_done = {}   # (c,stage) -> finish of last piece
        self.req = {c:{s[0]:s for s in stage_specs(c)} for c in CIRCUITS}
        self.placed_h = {}     # (c,stage) -> hours placed
        self.n = 0
    def prereq_time(self, c, stage):
        order = ['HYDRO','INITIAL_FLUSH','CHEM_CLEAN','DRAIN_RINSE','PASSIVATE','HOLD','FINAL_FILL']
        i = order.index(stage)
        t = 0.0
        for st in order[:i]:
            if st in self.req[c]:
                if (c,st) in self.stage_done and self.placed_h.get((c,st),0) + 1e-6 >= self.req[c][st][1]:
                    t = max(t, self.stage_done[(c,st)])
                elif st in self.req[c]:
                    # stage not completed yet
                    if st != stage: return None
        if stage == 'DRAIN_RINSE':
            dn = donor_of(c)
            if dn:
                if (dn,'DRAIN_RINSE') in self.stage_done and self.placed_h.get((dn,'DRAIN_RINSE'),0)+1e-6 >= self.req[dn]['DRAIN_RINSE'][1]:
                    t = max(t, self.stage_done[(dn,'DRAIN_RINSE')])
                else:
                    return None
        return t
    def add(self, c, stage, crew=None, skids=None, hours=None, not_before=0.0, start=None):
        if skids is None and stage not in ('HYDRO','HOLD'):
            raise ValueError('skids needed')
        req = self.req[c][stage][1]
        done = self.placed_h.get((c,stage),0.0)
        if hours is None: hours = req - done
        dur = math.ceil(hours*1000 - 1e-6)/1000.0
        t = self.prereq_time(c, stage)
        if t is None: raise ValueError(f'prereq not met for {c} {stage}')
        if (c,stage) in self.stage_done: t = max(t, self.stage_done[(c,stage)])
        t = max(t, not_before)
        if crew: t = max(t, self.crew_free.get(crew, 0.0))
        for s in skids or []: t = max(t, self.skid_free[s])
        if start is not None:
            if start + 1e-9 < t: raise ValueError(f'{c} {stage} requested start {start} < earliest {t}')
            t = start
        t = r3(t); f = r3(t + dur)
        self.n += 1
        a = dict(id=f'A{self.n:03d}', circuit=c, stage=stage, start=t, finish=f, skids=list(skids or []), crew=crew)
        self.acts.append(a)
        if crew: self.crew_free[crew] = f
        for s in skids or []: self.skid_free[s] = f
        self.stage_done[(c,stage)] = f
        self.placed_h[(c,stage)] = done + (f - t)
        return a
    def hold(self, c, until=None):
        t = self.prereq_time(c, 'HOLD')
        f = r3(t + HOLD_H) if until is None else until
        return self.add(c, 'HOLD', hours=f-t)

def show(acts):
    for a in sorted(acts, key=lambda x:(x['start'], x['circuit'])):
        print(f"{a['id']} {a['circuit']} {a['stage']:14s} {a['start']:9.3f} {a['finish']:9.3f} {'+'.join(a['skids']) or '-':20s} {a['crew'] or '-'} w={a.get('water',0):.0f}")
