from sched import *

WCAP = 0.97
HYD = [c for c in CIRCUITS if not CIRCUITS[c]['hydro_ok']]

def unit_list(nsplit):
    units = ['H']
    for c in CIRCUITS:
        units.append(('FC',c))
        if c == 'C1':
            for i in range(nsplit): units.append(('R1',i))
            units.append(('P','C1'))
        else:
            units.append(('RP',c))
    return units

def prereqs(u, nsplit):
    if u == 'H': return []
    k, c = u
    if k == 'FC':
        return ['H'] if c in HYD else []
    if k == 'R1':
        p = [('FC','C1')]
        if c > 0: p.append(('R1',c-1))
        return p
    if k == 'P':
        return [('R1',nsplit-1)]
    if k == 'RP':
        p = [('FC',c)]
        dn = donor_of(c)
        if dn == 'C1': p.append(('P','C1'))   # rinse complete (P follows last piece)
        elif dn: p.append(('RP',dn))
        return p

def valid(seq, nsplit):
    pos = {u:i for i,u in enumerate(seq)}
    for u in seq:
        for p in prereqs(u, nsplit):
            if pos[p] > pos[u]: return False
    return True

def random_topo(nsplit, rng):
    units = unit_list(nsplit)
    placed = []; rem = set(range(len(units)))
    while rem:
        cand = [i for i in rem if all(p in placed for p in prereqs(units[i], nsplit))]
        i = rng.choice(cand); placed.append(units[i]); rem.remove(i)
    return placed

def water_by_day(acts_w):
    d = {}
    for (s,f,w) in acts_w:
        if w <= 0 or f <= s: continue
        for k in range(int(s//24), int(math.ceil(f/24))+1):
            ov = overlap(s,f,24*k,24*k+24)
            if ov > 0: d[k] = d.get(k,0) + w*ov/(f-s)
    return d

def decode(seq, sol, t0=0.0, crew='CREW-A', ff_mode='block'):
    """sol: dict with nsplit, skid choice per (circuit,'FC'/'RP') for C2,C3 ('1200' or 'AB'), fs600 unit per circuit"""
    nsplit = sol['nsplit']
