    done = {}
    dayw = {}
    def skids_for(c, part):
        if c == 'C1': return ['FS-1200-A']
        if c in ('C2','C3'):
            return ['FS-1200-A'] if sol['sk'][(c,part)] == '1200' else ['FS-600-A','FS-600-B']
        return [sol['u600'][c]]
    def fits(items):
        add = water_by_day(items)
        for k,w in add.items():
            if dayw.get(k,0) + w > total_limit(k)*WCAP + 1e-6: return False
        return True
    def commit(items):
        for k,w in water_by_day(items).items(): dayw[k] = dayw.get(k,0)+w
    nid = [0]
    def mk(c, st, s, f, sk, cr):
        nid[0] += 1
        return dict(id=f'A{nid[0]:03d}', circuit=c, stage=st, start=r3(s), finish=r3(f), skids=list(sk), crew=cr)
    for u in seq:
