            elif k == 'RP':
                sk = skids_for(c,'RP')
                parts = [(c,'DRAIN_RINSE',req[c]['DRAIN_RINSE'][1],sk),(c,'PASSIVATE',req[c]['PASSIVATE'][1],sk)]
        # earliest start
