            if fits(items): break
            e = (math.floor(e/12)+1)*12.0
            tries += 1
            if tries > 60: return None
        commit(items)
        tt = e
        for (c,st,h,sk) in parts:
            dur = math.ceil(h*1000-1e-6)/1000.0
            a = mk(c, st, tt, tt+dur, sk, crew if st != 'HOLD' else None)
            acts.append(a); tt = r3(tt+dur)
            for s in sk: skid_free[s] = tt
        t = tt
        done[u] = tt
    # final fills
    pass_end = {c: max(a['finish'] for a in acts if a['circuit']==c and a['stage']=='PASSIVATE') for c in CIRCUITS}
    hold_end = {c: pass_end[c] + HOLD_H for c in CIRCUITS}
    tff = math.ceil(max(hold_end.values())/12 - 1e-9)*12.0
    ffo = sol.get('fforder', ['C1','C2','C3','C4','C5','C6','C7','C8'])
    tt = tff
