def default_sol(nsplit=3):
    return dict(nsplit=nsplit, split={i:1.0/nsplit for i in range(nsplit)},
                sk={('C2','FC'):'1200',('C2','RP'):'1200',('C3','FC'):'1200',('C3','RP'):'1200'},
                u600={c:'FS-600-A' for c in ['C4','C5','C6','C7','C8']}, skff={}, u600ff='FS-600-A')

def cost_of(seq, sol, t0):
    acts = decode(seq, sol, t0)
    if acts is None: return 1e12, None, None
    res = evaluate(acts)
    pen = 1e6*len(res['viol'])
    return res['total'] + pen, acts, res

def anneal(seed, iters=4000, nsplit=3, t0s=(0.0,12.0,24.0,36.0,48.0,60.0,72.0,96.0,120.0,132.0,136.0)):
    rng = random.Random(seed)
    sol = default_sol(nsplit)
    seq = random_topo(nsplit, rng)
    t0 = rng.choice(t0s)
    cur, _, _ = cost_of(seq, sol, t0)
    best = (cur, list(seq), copy.deepcopy(sol), t0)
    T = 2000.0
    for it in range(iters):
        T = 2000.0*(1-it/iters) + 5
        nseq = list(seq); nsol = copy.deepcopy(sol); nt0 = t0
        m = rng.random()
        if m < 0.55:
            i, j = rng.randrange(len(nseq)), rng.randrange(len(nseq))
            u = nseq.pop(i); nseq.insert(j, u)
            if not valid(nseq, nsplit): continue
        elif m < 0.65:
            i = rng.randrange(len(nseq)-1)
            nseq[i], nseq[i+1] = nseq[i+1], nseq[i]
            if not valid(nseq, nsplit): continue
        elif m < 0.75:
            key = rng.choice(list(nsol['sk']))
            nsol['sk'][key] = 'AB' if nsol['sk'][key]=='1200' else '1200'
        elif m < 0.85:
